import {
  forwardRef,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";

import { cn } from "@/lib/cn";
import { canAnimate, motionEasing, readMotion } from "@/lib/motion";
import { Button, type ButtonProps } from "./button.js";
import { VisuallyHidden } from "./visually-hidden.js";

/** Props accepted by Fuse. */
export type FuseProps = {
  /** How long the fuse burns, in milliseconds: a decision window, not motion. */
  duration: number;
  /** Hold the burn, for example while the pointer rests on the action. */
  paused?: boolean;
  /** Called once when the fuse has burnt down. */
  onBurnt: () => void;
  className?: string;
};

/**
 * A hairline that burns down over its duration, then calls `onBurnt`. Its
 * thickness is the theme's `--stipe-motion-fuse` (0 hides it but the window
 * still runs). Under reduced motion it ticks down once a second instead of
 * burning smoothly.
 */
export function Fuse({
  duration,
  paused = false,
  onBurnt,
  className,
}: FuseProps) {
  const node = useRef<HTMLSpanElement>(null);
  const burn = useRef<Animation | null>(null);
  const burnt = useRef(onBurnt);
  useEffect(() => {
    burnt.current = onBurnt;
  }, [onBurnt]);

  useLayoutEffect(() => {
    const element = node.current;
    if (!element) return;
    if (!canAnimate(element)) {
      const timer = setTimeout(() => {
        burnt.current();
      }, duration);
      return () => {
        clearTimeout(timer);
      };
    }
    const motion = readMotion(element);
    const seconds = Math.max(1, Math.round(duration / 1000));
    const animation = element.animate(
      [{ transform: "scaleX(1)" }, { transform: "scaleX(0)" }],
      {
        duration,
        easing: motion.reduced
          ? `steps(${String(seconds)}, end)`
          : motionEasing(motion, "linear"),
        fill: "forwards",
      },
    );
    animation.addEventListener("finish", () => {
      burnt.current();
    });
    burn.current = animation;
    return () => {
      animation.cancel();
      burn.current = null;
    };
  }, [duration]);

  useEffect(() => {
    const animation = burn.current;
    if (!animation) return;
    if (paused) animation.pause();
    else if (animation.playState === "paused") animation.play();
  }, [paused]);

  return (
    <span
      ref={node}
      aria-hidden="true"
      className={cn("caps-fuse", className)}
    />
  );
}

/** Props accepted by UndoAction. */
export type UndoActionProps = {
  /** The action's label, such as "Stop". */
  children: ReactNode;
  /** Runs when the undo window closes without an undo: the action happens then. */
  onCommit: () => void;
  /** Spoken when the action is armed, such as "Port 5173 stops in 5 seconds". */
  armedAnnouncement: string;
  /** Spoken after an undo, such as "Port 5173 kept open". */
  undoneAnnouncement: string;
  undoLabel?: ReactNode;
  /** The undo window in milliseconds. */
  undoMs?: number;
} & Omit<ButtonProps, "children" | "onClick" | "result" | "resultLabel">;

/**
 * A destructive action that waits for its undo window instead of asking
 * first. Pressing it turns the same button into Undo with a fuse burning along
 * its edge; Undo or Escape cancels, and the action commits when the fuse runs
 * out. Resting the pointer on it holds the fuse.
 */
export const UndoAction = forwardRef<HTMLButtonElement, UndoActionProps>(
  function UndoAction(
    {
      children,
      onCommit,
      armedAnnouncement,
      undoneAnnouncement,
      undoLabel = "Undo",
      undoMs = 5000,
      className,
      onKeyDown,
      onPointerEnter,
      onPointerLeave,
      ...props
    },
    ref,
  ) {
    const [armed, setArmed] = useState(false);
    const [held, setHeld] = useState(false);
    const [spoken, setSpoken] = useState("");
    const hint = useId();
    const undo = () => {
      setArmed(false);
      setSpoken(undoneAnnouncement);
    };
    return (
      <>
        <Button
          {...props}
          ref={ref}
          aria-label={armed ? undefined : props["aria-label"]}
          aria-labelledby={armed ? undefined : props["aria-labelledby"]}
          aria-describedby={armed ? hint : props["aria-describedby"]}
          className={cn("caps-undo-action", className)}
          data-armed={armed ? "" : undefined}
          onClick={() => {
            if (armed) {
              undo();
              return;
            }
            setArmed(true);
            setSpoken(armedAnnouncement);
          }}
          onKeyDown={(event) => {
            onKeyDown?.(event);
            if (armed && event.key === "Escape") {
              event.preventDefault();
              undo();
            }
          }}
          onPointerEnter={(event) => {
            onPointerEnter?.(event);
            setHeld(true);
          }}
          onPointerLeave={(event) => {
            onPointerLeave?.(event);
            setHeld(false);
          }}
        >
          {armed ? undoLabel : children}
          {armed ? (
            <Fuse
              duration={undoMs}
              paused={held}
              onBurnt={() => {
                setArmed(false);
                setSpoken("");
                onCommit();
              }}
            />
          ) : null}
        </Button>
        <VisuallyHidden id={hint}>Press Escape to undo.</VisuallyHidden>
        <VisuallyHidden role="status">{spoken}</VisuallyHidden>
      </>
    );
  },
);

import {
  forwardRef,
  useEffect,
  useId,
  useRef,
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode,
} from "react";

import { cn } from "@/lib/cn";
import { canAnimate, motionEasing, readMotion } from "@/lib/motion";
import { Button, type ButtonProps } from "./button.js";
import { VisuallyHidden } from "./visually-hidden.js";

/** Props accepted by HoldButton. */
export type HoldButtonProps = {
  children: ReactNode;
  /** Runs once the button has been held for `holdMs`. */
  onConfirm: () => void;
  /** How long to hold, in milliseconds: a deliberate pause, not motion. */
  holdMs?: number;
  /** Spoken description of the gesture. */
  holdHint?: string;
} & Omit<ButtonProps, "children" | "onClick">;

const confirmKeys = new Set(["Enter", " "]);

/**
 * For an action nothing can undo: press and hold (pointer, Space or Enter)
 * while a fill rises; let go early and it drops back; hold to the top and the
 * action runs. Under reduced motion the fill rises in three steps.
 */
export const HoldButton = forwardRef<HTMLButtonElement, HoldButtonProps>(
  function HoldButton(
    {
      children,
      onConfirm,
      holdMs = 900,
      holdHint = "Press and hold to confirm.",
      className,
      disabled,
      loading = false,
      result,
      resultLabel,
      onBlur,
      onKeyDown,
      onKeyUp,
      onPointerDown,
      onPointerUp,
      onPointerLeave,
      onPointerCancel,
      ...props
    },
    ref,
  ) {
    const fill = useRef<HTMLSpanElement>(null);
    const rising = useRef<Animation | null>(null);
    const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
    const confirm = useRef(onConfirm);
    const hint = useId();
    useEffect(() => {
      confirm.current = onConfirm;
    }, [onConfirm]);
    useEffect(
      () => () => {
        rising.current?.cancel();
        if (timer.current !== null) clearTimeout(timer.current);
      },
      [],
    );

    const finish = () => {
      rising.current = null;
      timer.current = null;
      confirm.current();
      const element = fill.current;
      if (!element || !canAnimate(element)) return;
      const motion = readMotion(element);
      element.animate([{ opacity: 1 }, { opacity: 0 }], {
        duration: motion.normal,
        easing: motionEasing(motion, motion.easeExit),
      });
    };

    const start = () => {
      const element = fill.current;
      if (
        disabled === true ||
        loading ||
        !element ||
        rising.current ||
        timer.current
      )
        return;
      if (!canAnimate(element)) {
        timer.current = setTimeout(finish, holdMs);
        return;
      }
      const motion = readMotion(element);
      const animation = element.animate(
        [{ transform: "scaleY(0)" }, { transform: "scaleY(1)" }],
        {
          duration: holdMs,
          easing: motion.reduced
            ? "steps(3, end)"
            : motionEasing(motion, "cubic-bezier(0.3, 0, 0.7, 1)"),
        },
      );
      animation.addEventListener("finish", finish);
      rising.current = animation;
    };

    const release = () => {
      if (timer.current !== null) {
        clearTimeout(timer.current);
        timer.current = null;
      }
      const animation = rising.current;
      const element = fill.current;
      if (!animation || !element) return;
      rising.current = null;
      // Drop back from wherever the fill had reached.
      const reached = getComputedStyle(element).transform;
      animation.cancel();
      const motion = readMotion(element);
      element.animate(
        [
          { transform: reached === "none" ? "scaleY(0)" : reached },
          { transform: "scaleY(0)" },
        ],
        { duration: motion.fast, easing: motionEasing(motion, motion.ease) },
      );
    };

    return (
      <>
        <Button
          {...props}
          ref={ref}
          disabled={disabled}
          loading={loading}
          result={result}
          // Only the label repeats on the result face; the hold fill owns one ref.
          resultLabel={
            resultLabel ?? (result === undefined ? undefined : children)
          }
          aria-describedby={hint}
          className={cn("caps-hold-button", className)}
          onBlur={(event) => {
            release();
            onBlur?.(event);
          }}
          onPointerDown={(event: PointerEvent<HTMLButtonElement>) => {
            onPointerDown?.(event);
            if (event.button === 0) start();
          }}
          onPointerUp={(event: PointerEvent<HTMLButtonElement>) => {
            onPointerUp?.(event);
            release();
          }}
          onPointerLeave={(event: PointerEvent<HTMLButtonElement>) => {
            onPointerLeave?.(event);
            release();
          }}
          onPointerCancel={(event: PointerEvent<HTMLButtonElement>) => {
            onPointerCancel?.(event);
            release();
          }}
          onKeyDown={(event: KeyboardEvent<HTMLButtonElement>) => {
            onKeyDown?.(event);
            if (event.key === "Escape") release();
            if (!confirmKeys.has(event.key)) return;
            event.preventDefault();
            if (!event.repeat) start();
          }}
          onKeyUp={(event: KeyboardEvent<HTMLButtonElement>) => {
            onKeyUp?.(event);
            if (!confirmKeys.has(event.key)) return;
            event.preventDefault();
            release();
          }}
        >
          <span ref={fill} aria-hidden="true" className="caps-hold-fill" />
          {children}
        </Button>
        <VisuallyHidden id={hint}>{holdHint}</VisuallyHidden>
      </>
    );
  },
);

import { useEffect, useState, type ReactNode } from "react";
import { toast } from "sonner";

import { Alert } from "./alert.js";
import { Button } from "./button.js";
import { Fuse } from "./undo-action.js";

/** What an undo toast says and does. */
export type UndoToastOptions = Readonly<{
  title: ReactNode;
  description?: ReactNode;
  /** Runs when the toast's fuse burns out: the action happens then. */
  onCommit: () => void;
  /** Runs when the person undoes, by the button or Escape. */
  onUndo?: () => void;
  undoLabel?: string;
  /** The undo window in milliseconds. */
  undoMs?: number;
  /** The Toaster to show it on, when a page has more than one. */
  toasterId?: string;
}>;

function UndoToast({
  dismiss,
  options,
}: {
  dismiss: () => void;
  options: UndoToastOptions;
}) {
  const [held, setHeld] = useState(false);
  const [settled, setSettled] = useState(false);
  const undo = () => {
    if (settled) return;
    setSettled(true);
    options.onUndo?.();
    dismiss();
  };
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (event.key !== "Escape" || settled) return;
      setSettled(true);
      options.onUndo?.();
      dismiss();
    };
    globalThis.addEventListener("keydown", onKey);
    return () => {
      globalThis.removeEventListener("keydown", onKey);
    };
  }, [settled, options, dismiss]);
  return (
    <div
      className="caps-undo-toast"
      onPointerEnter={() => {
        setHeld(true);
      }}
      onPointerLeave={() => {
        setHeld(false);
      }}
      onFocus={() => {
        setHeld(true);
      }}
      onBlur={() => {
        setHeld(false);
      }}
    >
      <Alert
        title={options.title}
        description={options.description}
        tone="info"
        action={
          <Button size="sm" variant="outline" onClick={undo}>
            {options.undoLabel ?? "Undo"}
          </Button>
        }
      />
      <Fuse
        duration={options.undoMs ?? 5000}
        paused={held}
        onBurnt={() => {
          if (settled) return;
          setSettled(true);
          options.onCommit();
          dismiss();
        }}
      />
    </div>
  );
}

/**
 * Show a done-and-undoable toast: the action is deferred while a fuse burns
 * along the toast's edge, Undo or Escape cancels it, and resting on the toast
 * holds the fuse. Returns the toast id.
 */
export function toastUndo(options: UndoToastOptions): string | number {
  const settings: Parameters<typeof toast.custom>[1] = { duration: Infinity };
  if (options.toasterId !== undefined) settings.toasterId = options.toasterId;
  return toast.custom(
    (id) => (
      <UndoToast
        options={options}
        dismiss={() => {
          toast.dismiss(id);
        }}
      />
    ),
    settings,
  );
}

import {
  useLayoutEffect,
  useState,
  useSyncExternalStore,
  type RefObject,
} from "react";

/** Resolved, element-scoped motion. Times are milliseconds and distances pixels. */
export type Motion = Readonly<{
  reduced: boolean;
  squish: number;
  fast: number;
  normal: number;
  slow: number;
  springDuration: number;
  bounce: number;
  stretch: number;
  distance: number;
  stagger: number;
  blur: number;
  shake: number;
  steps: number;
  fuse: number;
  pressDepth: number;
  pressScale: number;
  ease: string;
  easeExit: string;
}>;

const defaults: Motion = Object.freeze({
  reduced: false,
  squish: 90,
  fast: 120,
  normal: 180,
  slow: 280,
  springDuration: 320,
  bounce: 0.3,
  stretch: 0.28,
  distance: 4,
  stagger: 24,
  blur: 0,
  shake: 3,
  steps: 0,
  fuse: 1,
  pressDepth: 0.5,
  pressScale: 1,
  ease: "cubic-bezier(0.2, 0, 0, 1)",
  easeExit: "cubic-bezier(0.4, 0, 1, 1)",
});

const preference = "(prefers-reduced-motion: reduce)";

/** Read at an event boundary; no root-theme lookup, so nested tokens win. */
export function readMotion(element: Element): Motion {
  const view = element.ownerDocument.defaultView;
  if (!view) return defaults;
  const style = view.getComputedStyle(element);
  const number = (name: string, fallback: number) => {
    const value = style.getPropertyValue(name).trim();
    const parsed = Number.parseFloat(value);
    return Number.isFinite(parsed) ? Math.max(0, parsed) : fallback;
  };
  const time = (name: string, fallback: number) => {
    const value = style.getPropertyValue(name).trim();
    return (
      number(name, fallback) *
      (value.endsWith("s") && !value.endsWith("ms") ? 1000 : 1)
    );
  };
  const browser: Partial<Pick<Window, "matchMedia">> = view;
  const reduced = browser.matchMedia?.(preference).matches ?? false;
  const duration = (name: string, fallback: number) =>
    reduced ? 120 : time(`--stipe-motion-${name}`, fallback);
  const amount = (name: string, fallback: number) =>
    reduced ? 0 : number(`--stipe-motion-${name}`, fallback);
  return {
    reduced,
    squish: duration("squish", defaults.squish),
    fast: duration("fast", defaults.fast),
    normal: duration("normal", defaults.normal),
    slow: duration("slow", defaults.slow),
    springDuration: duration("spring-duration", defaults.springDuration),
    bounce: Math.min(1, amount("bounce", defaults.bounce)),
    stretch: amount("stretch", defaults.stretch),
    distance: amount("distance", defaults.distance),
    stagger: reduced ? 0 : time("--stipe-motion-stagger", defaults.stagger),
    blur: amount("blur", defaults.blur),
    shake: amount("shake", defaults.shake),
    steps: Math.floor(amount("steps", defaults.steps)),
    fuse: number("--stipe-motion-fuse", defaults.fuse),
    pressDepth: reduced
      ? 0
      : number("--stipe-press-depth", defaults.pressDepth),
    pressScale: reduced
      ? 1
      : number("--stipe-press-scale", defaults.pressScale),
    ease: style.getPropertyValue("--stipe-motion-ease").trim() || defaults.ease,
    easeExit:
      style.getPropertyValue("--stipe-motion-ease-exit").trim() ||
      defaults.easeExit,
  };
}

/** Live motion tokens for a mounted ref, including nested theme and OS changes. */
export function useMotion(ref: RefObject<Element | null>): Motion {
  const [motion, setMotion] = useState<Motion>(() => ({
    ...defaults,
    reduced: true,
  }));
  useLayoutEffect(() => {
    const element = ref.current;
    const view = element?.ownerDocument.defaultView;
    if (!element || !view) return;
    const update = () => {
      const next = readMotion(element);
      setMotion((previous) =>
        JSON.stringify(previous) === JSON.stringify(next) ? previous : next,
      );
    };
    update();
    const observer = new view.MutationObserver(update);
    // Observe ancestors only: animation writes to descendants must not trigger reads.
    for (
      let parent: Element | null = element;
      parent;
      parent = parent.parentElement
    ) {
      observer.observe(parent, {
        attributes: true,
        attributeFilter: ["data-theme", "class", "style"],
      });
    }
    const browser: Partial<Pick<Window, "matchMedia">> = view;
    const media = browser.matchMedia?.(preference);
    media?.addEventListener("change", update);
    return () => {
      observer.disconnect();
      media?.removeEventListener("change", update);
    };
  }, [ref]);
  return motion;
}

/** Today's feel: the defaults that components' authored timings are written against. */
export const motionDefaults: Motion = defaults;

/**
 * Scale one of a component's authored durations by the theme's tempo
 * (`--stipe-motion-normal` against its 180ms default). Today's themes return
 * the authored value unchanged; reduced motion returns 0 (nothing travels).
 */
export function motionTime(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  return Math.round((authored * motion.normal) / defaults.normal);
}

/**
 * Scale one of a component's authored spring bounces by the theme's bounce
 * (`--stipe-motion-bounce` against its 0.3 default), so a lively control stays
 * livelier than a calm one inside every theme. A 0 theme is critically damped.
 */
export function motionBounce(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  const scaled = (authored * motion.bounce) / defaults.bounce;
  return Math.min(0.9, Math.max(0, scaled));
}

/** Scale an authored spring settle time by `--stipe-motion-spring-duration`. */
export function motionSpringTime(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  return Math.round(
    (authored * motion.springDuration) / defaults.springDuration,
  );
}

/** A CSS easing for a Web Animation, stepped when the theme asks for it. */
export function motionEasing(motion: Motion, ease: string): string {
  return motion.steps > 0 ? `steps(${String(motion.steps)}, end)` : ease;
}

/** Whether the element can run Web Animations (not in jsdom or old engines). */
export function canAnimate(element: Element): boolean {
  return "animate" in element;
}

const globalWindow: Partial<Pick<Window, "matchMedia">> = globalThis;

function prefersReducedMotion(): boolean {
  return globalWindow.matchMedia?.(preference).matches ?? false;
}

function subscribeReducedMotion(update: () => void) {
  const media = globalWindow.matchMedia?.(preference);
  media?.addEventListener("change", update);
  return () => {
    media?.removeEventListener("change", update);
  };
}

/** Server renders assume reduced motion, so hydration never starts mid-move. */
function serverReducedMotion() {
  return true;
}

/**
 * The live reduced-motion preference alone, for controls that only need to
 * know whether to move (their timing comes from `readMotion` when they do).
 */
export function useReducedMotion(): boolean {
  return useSyncExternalStore(
    subscribeReducedMotion,
    prefersReducedMotion,
    serverReducedMotion,
  );
}

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}
